            "id": "light-literature-gaps",
            "kind": "literature-gaps",
            "chapter": "1 · Illumination",
            "topicId": "illumination",
            "title": "Gaps and problems identified from the literature",
            "lead": "What still needs to be resolved for a coherent, useful, live mixed-reality lighting preview?",
            "points": [],
            "paperIds": [
              "review-ref-85",
              "review-ref-35",
              "review-ref-65",
              "review-ref-33",
              "handlight",
              "review-ref-75",
              "review-ref-1",
              "review-ref-2"
            ],
            "branchIds": [],
            "sourceRefs": [],
            "problems": [
              {
                "label": "Shadow errors",
                "text": "HybRelighter cannot consistently separate real shadows from reconstruction errors.",
                "paperIds": [
                  "review-ref-85"
                ],
                "status": "reported"
              },
              {
                "label": "Material accuracy",
                "text": "Reciprocal Shading does not recover real reflectance and omits specular terms.",
                "paperIds": [
                  "review-ref-35"
                ],
                "status": "reported"
              },
              {
                "label": "Hidden geometry",
                "text": "Unseen scene geometry is absent from the screen-space reconstruction, limiting lighting consistency.",
                "paperIds": [
                  "review-ref-35"
                ],
                "status": "reported"
              },
              {
                "label": "Indirect light",
                "text": "The near-field AR baseline omits indirect light bouncing from virtual objects onto real objects.",
                "paperIds": [
                  "review-ref-65"
                ],
                "status": "reported"
              },
              {
                "label": "Glossy surfaces",
                "text": "The near-field AR baseline does not support highly glossy virtual objects or general material reflectance.",
                "paperIds": [
                  "review-ref-65"
                ],
                "status": "reported"
              },
              {
                "label": "Lighting-update delay",
                "text": "Interactive display rates can conceal slower lighting updates, leaving virtual content behind changes in the real scene.",
                "paperIds": [
                  "review-ref-65"
                ],
                "status": "reported"
              },
              {
                "label": "Stereo MR",
                "text": "Stereo headset rendering remains unvalidated by methods demonstrated without stereo output.",
                "paperIds": [
                  "review-ref-33"
                ],
                "status": "scope"
              },
              {
                "label": "Local-probe reliability",
                "text": "Hand-based probes need testing at new virtual-object positions as the hand, light and scene change.",
                "paperIds": [
                  "handlight"
                ],
                "status": "question"
              },
              {
                "label": "Live scene updates",
                "text": "Fast lighting-volume queries do not establish that the complete spatial-estimation pipeline can update live.",
                "paperIds": [
                  "review-ref-75"
                ],
                "status": "question"
              },
              {
                "label": "Task benefit",
                "text": "Whether shared lighting improves prop placement or contact judgments remains a task-specific question.",
                "paperIds": [
                  "review-ref-1",
                  "review-ref-33"
                ],
                "status": "question"
              },
              {
                "label": "Necessary cue fidelity",
                "text": "Which shadow and shading approximations preserve task performance across materials and backgrounds remains to be tested.",
                "paperIds": [
                  "review-ref-2"
                ],
                "status": "question"
              },
              {
                "label": "Practical deployment",
                "text": "Reducing tracking, calibration and compute requirements while preserving the required lighting cues remains a deployment challenge.",
                "paperIds": [
                  "review-ref-33",
                  "review-ref-65"
                ],
                "status": "question"
              }
            ],
